---@param clickCallback fun(luaIndex:number):void
function WhiteLevelGiftCellNode:SetClickCB(clickCallback)
    self.clickCallback_ = clickCallback
end

function WhiteLevelGiftCellNode:Awake()
    self.BigTxtPriceOldNum = self.BigDiscountNode.transform:Find("TxtPriceOld")
    self.lightGlowTrans = self.TextValue.transform.parent:Find("ImgBgLight")
    self.imgPrice = self.TxtPrice.transform.parent:Find("ImgPrice")
    CfUtils.SetActive(self.lightGlowTrans, false)
    self.discountNode = self.BigDiscountNode.transform.parent:Find("DiscountNode")
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerLevel = playerComponent.playerDojo.level
    self.playerLevel = checkNumber(playerLevel)
    SetButtonAction(self.TxtRenewal.transform.parent.parent, function()
        --调用支付的逻辑
        if self.clickCallback_ then
            if checkNumber(self.cellData.level) > self.playerLevel then
                GameUtils.Toast(localize('未达到该等级不能购买'))
                return
            end
            if not isNull(self.cellData.preGift) and checkNumber(self.cellData.preGift.hasBuy) == 0 then
                GameUtils.Toast(localize('购买前置礼包解锁'))
                return
            end
            xRecord.record('4-009', 'click_lvl_pack'.. tostring(self.cellData.id))
            self.clickCallback_(self.cellData, self.playerLevel)
        end
    end)
    SetButtonAction(self.SellOutBtn, function()
        ----售罄
    end)
    self.handler = Events.AddListener(Constants.EventNames.WHITE_GIFT_TIME_EVENT, function(saleTime)
        self:OnTimerAction(saleTime)
    end)

    self.BtnNor = self.TxtRenewal.transform.parent.parent
    self.BtnNorBg = self.BtnNor:Find("ImgBg")
end

---OnTimerAction
---@param saleTime number
function WhiteLevelGiftCellNode:OnTimerAction(saleTime)
    if self.cellData and checkNumber(self.cellData.hasBuy) == 0 and checkNumber(self.cellData.level) <= self.playerLevel then
        if checkNumber(self.cellData.saleRemainTime) <= 0 then
            if not self.invoked then
                self.invoked = true
                local isLocked = checkNumber(self.cellData.level) > self.playerLevel
                if not isNull(self.cellData.preGift) and not isLocked then
                    isLocked =  checkNumber(self.cellData.preGift.hasBuy) == 0
                end
                CfUtils.SetActive(self.BigDiscountNode, false)
                CfUtils.SetActive(self.discountNode, not isLocked)
                CfUtils.SetActive(self.TxtRenewal, false)
                if not self.cellData:IsGoodExchange() then
                    CfUtils.SetActive(self.imgPrice, false)
                    local text = string.format_size_tag(CfUtils.GetCurrerySymbol(), 30)
                    local windowPriceId = CfUtils.GetWindowsPriceId(self.cellData.sourceProduct)
                    CfUtils.FillText(self.TxtPrice, text .. CfUtils.GetPrice(windowPriceId, self.cellData.sourceProduct.channelProductId))
                else
                    local dojo = table.takeFirst(table.values(self.cellData.prices))
                    local price = checkNumber(dojo.original)
                    CfUtils.FillText(self.TxtPrice, price)
                    CfUtils.SetActive(self.imgPrice, true)
                end
                self:FreshGoodNode(self.cellData)
            end
        else
            CfUtils.FillText(self.TxtPriceTime, CfUtils.GetTimeHMS3(self.cellData.saleRemainTime))
        end
    end
end

function WhiteLevelGiftCellNode:SetLuaIndex(index)
    self.index = index
end

function WhiteLevelGiftCellNode:FreshGoodNode(data)
    KTool.DestroyGameObjectChildren(self.GoodsListLight.gameObject, false)
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    if #data.rewards > 0 then
        for i, v in pairs(data.rewards) do
            local goodNode = KTool.Instantiate(self.GoodsListLight.gameObject, self.GoodNode.gameObject, false)
            goodNode.name = "GoodNode" .. tostring(i)
            CfUtils.SetActive(goodNode, true)
            ---@type GoodNodeMB
            local env = CfUtils.GetLuaScr(goodNode.gameObject, GoodNodeMBPath)
            ----@type GoodsVo
            local vo = goodsConfMgr:GetGoodsVoById(v.goodsId)
            if vo then
                env:SetClickButtonAction(function(goodsId, id)
                    ----点击出gip
                    GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id, true)
                end)
                env:Reload({ goodsId = vo.id, isShowNo = true, text = "x" .. v.num, id = vo.id })
            end
        end
    end
    local payPoint = checkNumber(data.sourceProduct.payPoint)
    if checkNumber(data.hasBuy) == 0 and checkNumber(data.level) <= self.playerLevel and checkNumber(data.saleRemainTime) > 0 then
        ---未被购买的情况下，存在优惠
        payPoint = checkNumber(data.saleProduct.payPoint)
    end
    if payPoint > 0 then
        local goodNode = KTool.Instantiate(self.GoodsListLight.gameObject, self.GoodNode.gameObject, false)
        goodNode.name = "GoodNode111"
        CfUtils.SetActive(goodNode, true)
        ---@type GoodNodeMB
        local env = CfUtils.GetLuaScr(goodNode.gameObject, GoodNodeMBPath)
        local PointGoodId = 3000099
        ----@type GoodsVo
        local vo = goodsConfMgr:GetGoodsVoById(PointGoodId)
        if vo then
            env:SetClickButtonAction(function(goodsId, id)
                ----点击出gip
                GameUtils.ShowCommonTipsBoard(goodNode, vo.name, vo.desc, vo.quality, vo.id, true)
            end)
            env:Reload({ goodsId = vo.id, isShowNo = true, text = "x" .. payPoint, id = vo.id })
        end
    end
end

