        Events.RemoveListener(Constants.EventNames.WHITE_GIFT_TIME_EVENT, self.handler)
    end
    self.handler = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return WhiteLevelGiftCellNode